from flask import Flask, jsonify, request
from typing import List, Dict, Any
import uuid
from datetime import datetime

app = Flask(__name__)

# In-memory storage (replace with database in production)
users: List[Dict[str, Any]] = []
posts: List[Dict[str, Any]] = []

class User:
    def __init__(self, name: str, email: str = None):
        self.id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self.created_at = datetime.now().isoformat()

    def to_dict(self):
        return {
            'id': self.id,
            'name': self.name,
            'email': self.email,
            'created_at': self.created_at
        }

class Post:
    def __init__(self, title: str, content: str, user_id: str):
        self.id = str(uuid.uuid4())
        self.title = title
        self.content = content
        self.user_id = user_id
        self.created_at = datetime.now().isoformat()

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'content': self.content,
            'user_id': self.user_id,
            'created_at': self.created_at
        }

# Error handling
@app.errorhandler(404)
def not_found(error):
    return jsonify({"error": "Resource not found"}), 404

@app.errorhandler(500)
def internal_error(error):
    return jsonify({"error": "Internal server error"}), 500

@app.errorhandler(400)
def bad_request(error):
    return jsonify({"error": "Bad request"}), 400

# User routes
@app.route("/users", methods=["GET"])
def get_users() -> Any:
    """Get all users"""
    try:
        return jsonify({
            "users": [user.to_dict() for user in users],
            "count": len(users)
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/users", methods=["POST"])
def create_user() -> Any:
    """Create a new user"""
    try:
        data = request.get_json()

        # Validation
        if not data:
            return jsonify({"error": "No data provided"}), 400

        if "name" not in data:
            return jsonify({"error": "Name is required"}), 400

        if not isinstance(data["name"], str) or not data["name"].strip():
            return jsonify({"error": "Name must be a non-empty string"}), 400

        # Create user
        user = User(name=data["name"].strip(), email=data.get("email"))
        users.append(user)

        return jsonify(user.to_dict()), 201

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/users/<user_id>", methods=["GET"])
def get_user(user_id: str) -> Any:
    """Get a specific user by ID"""
    try:
        user = next((u for u in users if u.id == user_id), None)
        if not user:
            return jsonify({"error": "User not found"}), 404

        return jsonify(user.to_dict())
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/users/<user_id>", methods=["PUT"])
def update_user(user_id: str) -> Any:
    """Update an existing user"""
    try:
        user = next((u for u in users if u.id == user_id), None)
        if not user:
            return jsonify({"error": "User not found"}), 404

        data = request.get_json()
        if not data:
            return jsonify({"error": "No data provided"}), 400

        # Update fields
        if "name" in data:
            if not isinstance(data["name"], str) or not data["name"].strip():
                return jsonify({"error": "Name must be a non-empty string"}), 400
            user.name = data["name"].strip()

        if "email" in data:
            user.email = data["email"]

        return jsonify(user.to_dict())
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/users/<user_id>", methods=["DELETE"])
def delete_user(user_id: str) -> Any:
    """Delete a user"""
    try:
        global users
        user_index = next((i for i, u in enumerate(users) if u.id == user_id), None)

        if user_index is None:
            return jsonify({"error": "User not found"}), 404

        # Remove user and associated posts
        deleted_user = users.pop(user_index)
        posts[:] = [p for p in posts if p.user_id != user_id]

        return jsonify({"message": "User deleted successfully", "deleted_user": deleted_user.to_dict()})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# Post routes
@app.route("/posts", methods=["GET"])
def get_posts() -> Any:
    """Get all posts with optional user filtering"""
    try:
        user_id = request.args.get('user_id')
        if user_id:
            filtered_posts = [p for p in posts if p.user_id == user_id]
            return jsonify({
                "posts": [p.to_dict() for p in filtered_posts],
                "count": len(filtered_posts),
                "filtered_by": f"user_id={user_id}"
            })

        return jsonify({
            "posts": [p.to_dict() for p in posts],
            "count": len(posts)
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/posts", methods=["POST"])
def create_post() -> Any:
    """Create a new post"""
    try:
        data = request.get_json()

        # Validation
        if not data:
            return jsonify({"error": "No data provided"}), 400

        required_fields = ["title", "content", "user_id"]
        missing_fields = [field for field in required_fields if field not in data]
        if missing_fields:
            return jsonify({"error": f"Missing required fields: {', '.join(missing_fields)}"}), 400

        # Verify user exists
        user_exists = any(u.id == data["user_id"] for u in users)
        if not user_exists:
            return jsonify({"error": "User not found"}), 404

        # Create post
        post = Post(
            title=data["title"],
            content=data["content"],
            user_id=data["user_id"]
        )
        posts.append(post)

        return jsonify(post.to_dict()), 201

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/posts/<post_id>", methods=["GET"])
def get_post(post_id: str) -> Any:
    """Get a specific post by ID"""
    try:
        post = next((p for p in posts if p.id == post_id), None)
        if not post:
            return jsonify({"error": "Post not found"}), 404

        return jsonify(post.to_dict())
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/posts/<post_id>", methods=["PUT"])
def update_post(post_id: str) -> Any:
    """Update an existing post"""
    try:
        post = next((p for p in posts if p.id == post_id), None)
        if not post:
            return jsonify({"error": "Post not found"}), 404

        data = request.get_json()
        if not data:
            return jsonify({"error": "No data provided"}), 400

        # Update fields
        if "title" in data:
            post.title = data["title"]
        if "content" in data:
            post.content = data["content"]

        return jsonify(post.to_dict())
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/posts/<post_id>", methods=["DELETE"])
def delete_post(post_id: str) -> Any:
    """Delete a post"""
    try:
        global posts
        post_index = next((i for i, p in enumerate(posts) if p.id == post_id), None)

        if post_index is None:
            return jsonify({"error": "Post not found"}), 404

        deleted_post = posts.pop(post_index)
        return jsonify({"message": "Post deleted successfully", "deleted_post": deleted_post.to_dict()})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# Health check endpoint
@app.route("/health", methods=["GET"])
def health_check() -> Any:
    """API health check"""
    return jsonify({
        "status": "healthy",
        "timestamp": datetime.now().isoformat(),
        "users_count": len(users),
        "posts_count": len(posts)
    })

# Root endpoint
@app.route("/")
def root() -> Any:
    """API root endpoint with available routes"""
    return jsonify({
        "message": "Flask API is running",
        "version": "1.0.0",
        "endpoints": {
            "users": "/users",
            "posts": "/posts",
            "health": "/health"
        }
    })

if __name__ == "__main__":
    app.run(debug=True, host='0.0.0.0', port=5000)
```

## Key Features:

1. **Complete CRUD Operations**: Full Create, Read, Update, Delete for both users and posts
2. **Proper Error Handling**: Comprehensive error handling with appropriate HTTP status codes
3. **Data Validation**: Input validation for all endpoints
4. **RESTful Design**: Follows REST conventions
5. **Type Hints**: Better code documentation and IDE support
6. **UUIDs**: Use UUIDs instead of sequential IDs for better security
7. **Timestamps**: Track creation and update times
8. **Relationships**: Users can have associated posts
9. **Health Check**: Monitoring endpoint
10. **Documentation**: Clear endpoint documentation

